// Target for magic links / OAuth.
// Native: opened via gnosis-events://auth-callback?code=... ; params come from the expo-router route (works for
//   cold start and warm resume), with Linking URL as a fallback.
// Web (https://gnosis.events/auth-callback): supabase-js detects the session in the URL itself.
//   If the link carries ?via=app (only set by native builds using the https bridge), we first try to
//   hand off to the app at the FIXED gnosis-events://auth-callback scheme (no open redirect: the target
//   is hardcoded; only the auth params are forwarded), then fall back to finishing on web.
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Platform, Text, View } from 'react-native';
import * as Linking from 'expo-linking';
import { router, useLocalSearchParams } from 'expo-router';
import { authParamsFromUrl, completeFromParams, completeFromUrl, NATIVE_REDIRECT, type AuthParams } from '../lib/auth';
import { supabase } from '../lib/supabase';
import { PRODUCT_NAME } from '../lib/config';
import { colors } from '../lib/theme';

const one = (v: string | string[] | undefined) => (Array.isArray(v) ? v[0] : v) ?? null;
const AUTH_KEYS = ['code', 'token_hash', 'access_token', 'refresh_token', 'expires_in', 'expires_at', 'token_type', 'type', 'error', 'error_description', 'error_code'];

function forwardParams(search: string, hash: string): string {
  const out = new URLSearchParams();
  for (const src of [new URLSearchParams(search), new URLSearchParams(hash.replace(/^#/, ''))])
    src.forEach((v, k) => { if (AUTH_KEYS.includes(k)) out.set(k, v); });
  const q = out.toString();
  return q ? `?${q}` : '';
}

export default function AuthCallback() {
  const hookUrl = Linking.useURL();
  const params = useLocalSearchParams<Record<string, string>>();
  const done = useRef(false);
  const [msg, setMsg] = useState<string | null>(null);

  // Native. Read auth params from the ROUTE (expo-router already parsed the deep link), not from
  // Linking.useURL(): on a warm resume the 'url' event fires before this screen mounts, so useURL()
  // falls back to getInitialURL() - null or a stale cold-start link - and the code was never exchanged.
  useEffect(() => {
    if (Platform.OS === 'web' || done.current) return;
    const fromRoute: AuthParams = {
      code: one(params.code), token_hash: one(params.token_hash), type: one(params.type),
      access_token: one(params.access_token), refresh_token: one(params.refresh_token),
      error: one(params.error), error_description: one(params.error_description),
    };
    const hasRouteParams = Object.values(fromRoute).some(Boolean);
    (async () => {
      let p = fromRoute;
      if (!hasRouteParams) {
        // Fallback (e.g. params in a #fragment, which the router drops): live URL, then initial URL.
        const url = hookUrl ?? (await Linking.getInitialURL());
        if (!url || !/[?#&](code|access_token|token_hash|error_description)=/.test(url)) return; // wait for useURL / safety net
        p = authParamsFromUrl(url);
      }
      done.current = true;
      try {
        const ok = await completeFromParams(p);
        if (!ok) throw new Error('No session was created.');
        router.replace('/');
      } catch (e: any) {
        setMsg(`Sign-in link didn't work: ${e?.message ?? e}. Request a new link from the app on this phone.`);
        setTimeout(() => router.replace('/sign-in'), 4000);
      }
    })();
  }, [hookUrl, params.code, params.token_hash, params.access_token, params.error_description]);

  // Native safety net: never strand the user on a spinner.
  useEffect(() => {
    if (Platform.OS === 'web') return;
    const t = setTimeout(async () => {
      if (done.current) return;
      const { data } = await supabase.auth.getSession();
      router.replace(data.session ? '/' : '/sign-in');
    }, 8000);
    return () => clearTimeout(t);
  }, []);

  // Web (+ app bridge)
  useEffect(() => {
    if (Platform.OS !== 'web' || typeof window === 'undefined') return;
    const { search, hash } = window.location;
    const viaApp = new URLSearchParams(search).get('via') === 'app';
    const finishOnWeb = async () => {
      // PKCE codes are bound to the verifier stored by the client that requested them; this only
      // succeeds if sign-in was started in this browser. detectSessionInUrl normally handles it already.
      const { data } = await supabase.auth.getSession();
      if (!data.session) await completeFromUrl(window.location.href).catch(() => {});
      router.replace('/');
    };
    if (viaApp) {
      window.location.href = NATIVE_REDIRECT + forwardParams(search, hash);
      setMsg(`Opening the ${PRODUCT_NAME} app… If nothing happens, open the app and request a new link there.`);
      const t = setTimeout(finishOnWeb, 2500);
      return () => clearTimeout(t);
    }
    const t = setTimeout(finishOnWeb, 400);
    return () => clearTimeout(t);
  }, []);

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', padding: 24 }}>
      <ActivityIndicator color={colors.navy} />
      {msg ? <Text style={{ marginTop: 16, textAlign: 'center' }}>{msg}</Text> : null}
    </View>
  );
}
